from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def describe_image(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.CAPTION])
    description = result.caption.content
    return {'description': description}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def detect_image_text(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.TEXT])
    text_lines = [line.content for line in result.text.lines]
    return {'text': ' '.join(text_lines)}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def score_image_safety(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.ADULT])
    safety_score = result.adult.is_adult_content
    return {'safety_score': safety_score}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def get_vision_client(endpoint, api_key):
    return ImageAnalysisClient(endpoint, AzureKeyCredential(api_key))

from azure.ai.vision.imageanalysis.models import VisualFeatures


def normalize_labels(result):
    tags = sorted(result.tags.list, key=lambda tag: tag.confidence, reverse=True)
    return [{'name': tag.name, 'confidence': tag.confidence} for tag in tags]


def normalize_description(result):
    return result.caption.content


def normalize_text(result):
    return ' '.join([line.content for line in result.text.lines])


def normalize_safety_score(result):
    return result.adult.is_adult_content

from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential


def check_visual_labels_for_unsafe_text(text, config=None):
    config = config or {}
    with TextAnalyticsClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.detect_language(text)
        language = result[0].primary_language.name
        result = client.analyze_sentiment([text])
        sentiment_score = result[0].sentiment
        return {'language': language, 'sentiment_score': sentiment_score}

from azure.storage.blob import BlobServiceClient


def archive_image_analysis_artifacts(payload, analysis_results, config=None):
    config = config or {}
    blob_service_client = BlobServiceClient(account_url=config['storage_account_url'], credential=config['storage_account_key'])
    blob_client = blob_service_client.get_blob_client(container=config['container_name'], blob=payload['image_name'])
    blob_client.upload_blob(analysis_results, overwrite=True)
